"""TEN + PCM post-ASR timing authority (Transub Pro ``ten_pcm``).

Whisper/Qwen decide *text* and *order*. Absolute cue times come from:
  1) VAD speech islands used for ASR (fallback: keep prior bounds)
  2) PCM speech-active subspans inside each island
  3) char-weight allocation across those subspans
  4) waveform / silent / onset / hold / end-clamp polish

Never ForcedAligner, never CPS stretch as authority.
"""

from __future__ import annotations

import logging
import os
from typing import Any, Iterable

import numpy as np

from .speech_spans import pcm_speech_intervals
from .ten_pcm_allocate import allocate_on_timeline, char_weight
from .ten_pcm_polish import (
    clamp_cue_ends,
    delay_cues_to_onset,
    extend_cue_holds,
    shift_silent_cues_forward,
    snap_cues_to_waveform,
)

_log = logging.getLogger("transub_engine.asr.ten_pcm")
_SAMPLE_RATE = 16000
_MAX_SNAP_MS = 2500


def resolve_asr_timing_mode(
    vad_options: dict[str, Any] | None = None,
    *,
    request_timing: str | None = None,
) -> str:
    """Return ``ten_pcm`` (default) / ``off``.

    Sources (first wins): explicit request → vad_options.asrTiming →
    env ``TRANSUB_ENGINE_ASR_TIMING`` → ``ten_pcm``.
    """
    candidates: list[str] = []
    if request_timing is not None:
        candidates.append(str(request_timing))
    if isinstance(vad_options, dict):
        raw = vad_options.get("asrTiming", vad_options.get("asr_timing"))
        if raw is not None:
            candidates.append(str(raw))
    env = (os.environ.get("TRANSUB_ENGINE_ASR_TIMING") or "").strip()
    if env:
        candidates.append(env)
    for raw in candidates:
        key = str(raw or "").strip().lower()
        if key in ("0", "off", "false", "none", "disable", "disabled"):
            return "off"
        if key in ("ten_pcm", "ten-pcm", "pcm", "1", "on", "true", "default"):
            return "ten_pcm"
        if key in ("refine", "energy", "snap"):
            # Legacy aliases → still run the polish pack.
            return "ten_pcm"
    return "ten_pcm"


def _island_index(
    timeline: list[tuple[int, int]], t_ms: int
) -> tuple[int, int]:
    best_i = 0
    best_d = 10**18
    for i, (a, b) in enumerate(timeline):
        if a <= t_ms <= b:
            return i, 0
        mid = (a + b) // 2
        d = abs(t_ms - mid)
        if d < best_d:
            best_d = d
            best_i = i
    return best_i, best_d


def _pcm_spans_for_island_ms(
    pcm: np.ndarray,
    island: tuple[int, int],
    *,
    sample_rate: int = _SAMPLE_RATE,
) -> list[tuple[int, int]]:
    a_ms, b_ms = island
    a_s = a_ms / 1000.0
    b_s = b_ms / 1000.0
    i0 = max(0, int(round(a_s * sample_rate)))
    i1 = min(int(pcm.size), int(round(b_s * sample_rate)))
    if i1 <= i0 + 8:
        return [island]
    clip = pcm[i0:i1]
    spans_s = pcm_speech_intervals(
        clip,
        sample_rate,
        offset_s=a_s,
        frame_ms=10.0,
        end_pad_s=0.10,
    )
    if not spans_s:
        return [island]
    out: list[tuple[int, int]] = []
    for sa, sb in spans_s:
        out.append((int(round(sa * 1000)), int(round(sb * 1000))))
    return out if out else [island]


def _pack_onto_islands(
    cues: list[dict[str, Any]],
    pcm: np.ndarray,
    islands_ms: list[tuple[int, int]],
    *,
    sample_rate: int = _SAMPLE_RATE,
) -> tuple[list[dict[str, Any]], str]:
    if not cues:
        return [], "empty"
    if not islands_ms:
        return [dict(c) for c in cues], "no_islands"

    groups: list[list[dict[str, Any]]] = [[] for _ in islands_ms]
    kept_raw: list[dict[str, Any]] = []
    skipped_far = 0
    for cue in cues:
        if not isinstance(cue, dict):
            continue
        start_ms = int(round(float(cue.get("start") or 0) * 1000))
        end_ms = int(round(float(cue.get("end") or 0) * 1000))
        mid = (start_ms + end_ms) // 2
        idx, dist = _island_index(islands_ms, mid)
        if dist > _MAX_SNAP_MS:
            kept_raw.append(dict(cue))
            skipped_far += 1
            continue
        groups[idx].append(dict(cue))

    out: list[dict[str, Any]] = list(kept_raw)
    pcm_span_n = 0
    for island, group in zip(islands_ms, groups):
        if not group:
            continue
        spans = _pcm_spans_for_island_ms(pcm, island, sample_rate=sample_rate)
        pcm_span_n += len(spans)
        weights = [char_weight(str(c.get("text") or "")) for c in group]
        slots = allocate_on_timeline(weights, spans)
        span_lo = spans[0][0]
        span_hi = spans[-1][1]
        for cue, (a, b) in zip(group, slots):
            start = max(span_lo, a)
            end = min(span_hi, max(a + 200, b))
            if end <= start:
                end = min(span_hi, start + 200)
            if end <= start:
                continue
            item = dict(cue)
            item["start"] = round(start / 1000.0, 3)
            item["end"] = round(end / 1000.0, 3)
            out.append(item)

    out.sort(
        key=lambda c: (
            float(c.get("start") or 0),
            float(c.get("end") or 0),
            str(c.get("text") or ""),
        )
    )
    fixed: list[dict[str, Any]] = []
    for c in out:
        if fixed and float(c.get("start") or 0) < float(fixed[-1].get("end") or 0):
            start_s = float(fixed[-1].get("end") or 0)
            dur = max(float(c.get("end") or 0) - float(c.get("start") or 0), 0.12)
            item = dict(c)
            item["start"] = round(start_s, 3)
            item["end"] = round(start_s + dur, 3)
            fixed.append(item)
        else:
            fixed.append(c)

    detail = (
        f"islands={len(islands_ms)}; pcm_spans={pcm_span_n}; "
        f"cues={len(fixed)}/{len(cues)}; far={skipped_far}"
    )
    return fixed, detail


def _normalize_islands_ms(
    islands: Iterable[tuple[float, float]] | None,
) -> list[tuple[int, int]]:
    """Convert island (start, end) pairs in **seconds** to milliseconds."""
    out: list[tuple[int, int]] = []
    if not islands:
        return out
    for pair in islands:
        try:
            a, b = float(pair[0]), float(pair[1])
        except Exception:
            continue
        if b <= a:
            continue
        a_ms, b_ms = int(round(a * 1000)), int(round(b * 1000))
        if b_ms - a_ms >= 80:
            out.append((a_ms, b_ms))
    return out


def apply_ten_pcm_timing(
    cues: list[dict[str, Any]] | None,
    *,
    audio_f32: Any,
    sample_rate: int = _SAMPLE_RATE,
    islands: Iterable[tuple[float, float]] | None = None,
    media_end_s: float | None = None,
    reallocate: bool = True,
) -> tuple[list[dict[str, Any]], str]:
    """Re-time cues on TEN/PCM timeline then run the Pro polish chain.

    ``reallocate=False`` skips island/PCM re-slotting (ForcedAligner path) and
    only runs acoustic polish.
    """
    if not cues:
        return [], "empty"
    try:
        pcm = np.asarray(audio_f32, dtype=np.float32).reshape(-1)
    except Exception:
        return [dict(c) for c in cues if isinstance(c, dict)], "bad_pcm"
    if pcm.size < 16:
        return [dict(c) for c in cues if isinstance(c, dict)], "short_pcm"

    sr = max(1000, int(sample_rate or _SAMPLE_RATE))
    islands_ms = _normalize_islands_ms(islands)
    parts: list[str] = []

    if reallocate and islands_ms:
        packed, pack_detail = _pack_onto_islands(
            [c for c in cues if isinstance(c, dict)],
            pcm,
            islands_ms,
            sample_rate=sr,
        )
        parts.append(f"pack={pack_detail}")
    else:
        packed = [dict(c) for c in cues if isinstance(c, dict)]
        parts.append("pack=skip")

    polished, d1 = snap_cues_to_waveform(packed, pcm)
    parts.append(d1)
    silenced, d2 = shift_silent_cues_forward(polished, pcm)
    parts.append(d2)
    delayed, d3 = delay_cues_to_onset(silenced, pcm)
    parts.append(d3)
    held, d4 = extend_cue_holds(delayed, media_end_s=media_end_s)
    parts.append(d4)
    clamped, d5 = clamp_cue_ends(held, pcm)
    parts.append(d5)

    detail = "; ".join(parts)
    _log.info("ten_pcm: %s", detail)
    return clamped, detail


__all__ = [
    "apply_ten_pcm_timing",
    "resolve_asr_timing_mode",
]
